FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR

VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR

VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR

VAR
    headIndex   : DINT := 1;
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
END_VAR

// Reset logic (highest priority)
IF reset THEN
    headIndex   := 1;
    elementCount := 0;
    status      := 16#0000;
    prevEnqueue := FALSE;
    prevDequeue := FALSE;

// Enqueue request (rising edge)
ELSIF enqueue AND NOT prevEnqueue THEN
    IF elementCount < capacity THEN
        // Calculate tail position: ((headIndex - 1 + elementCount) MOD capacity) + 1
        buffer[((headIndex - 1 + elementCount) MOD capacity) + 1] := item;
        elementCount := elementCount + 1;
        status := 16#0000;
    ELSE
        status := 16#8002; // Queue full
    END_IF;
    prevEnqueue := enqueue;
    prevDequeue := dequeue;

// Dequeue request (rising edge)
ELSIF dequeue AND NOT prevDequeue THEN
    IF elementCount > 0 THEN
        item := buffer[headIndex];
        headIndex := (headIndex MOD capacity) + 1;
        elementCount := elementCount - 1;
        status := 16#0000;
    ELSE
        status := 16#8001; // Queue empty
    END_IF;
    prevEnqueue := enqueue;
    prevDequeue := dequeue;

// Idle or same state
ELSE
    status := 16#0000;
    prevEnqueue := enqueue;
    prevDequeue := dequeue;
END_IF;
END_FUNCTION_BLOCK
